#include <iostream>
using namespace std;

int main() {
    int n = 0;
    cin >> n;

    long long pairs = 0;
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            pairs = pairs + 1;
        }
    }

    cout << "{greet}" << endl;
    cout << "一共 " << pairs << " 圈" << endl;
    return 0;
}
